from ta_moler.cmd.hub.rfswcli.generichub import GenericHub


class NextPartition(GenericHub):
    """NextPartition command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Next_partition command.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(NextPartition, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                            runner=runner)
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        return "next_partition"


